"""KinDER i00 robot driver. All motion is issued through rcb_client."""
from rcb_client import Robot
import numpy as np

r = Robot()
spec = r.spec()


def status():
    return r.status()


def observe(cameras=None, depth=False):
    return r.get_obs(cameras=cameras, include_depth=depth, video='frames')


def delta(base=(0.0, 0.0, 0.0), arm=(0.0,)*7, gripper=0.0):
    row = np.array([*base, *arm, gripper], dtype=float)
    return row


def send(actions, cameras=('robot_base',), video='none', depth=False, note=''):
    actions = np.asarray(actions, dtype=float).reshape(-1, 11)
    return r.submit('delta', actions, cameras=list(cameras), video=video,
                    include_depth=depth, note=note)


if __name__ == '__main__':
    print('spec:', spec)
    print('status:', status())
    obs = observe(cameras=['robot_base', 'robot_wrist'], depth=True)
    obs.save('/app/output/initial_observation')
    print('observation:', obs.meta)
PY
